"""
Database migration script

This script reads SQL files from the ./migrations/ directory
and logs each filename it would apply, in order.
"""

const fs = require('fs');
const path = require('path');

// Directory containing migration files
const MIGRATIONS_DIR = './migrations';

/**
 * Get all migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them alphabetically
    const sqlFiles = files.filter(file => file.endsWith('.sql'));
    sqlFiles.sort();

    return sqlFiles;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      return [];
    }
    throw err;
  }
}

/**
 * Main migration function
 */
function migrate() {
